readDistances();let distTimer;window.addEventListener('resize',()=>{clearTimeout(distTimer);distTimer=setTimeout(readDistances,200);});const SHOWN={opacity:1,translate:'0px 0px',scale:1};function hiddenFrame(type,dir){switch(type){case 'zoom':return{opacity:0,scale:0.86,translate:'0px '+(Y*0.4*dir)+'px'};case 'fade':return{opacity:0};case 'left':return{opacity:0,translate:(-X)+'px 0px'};case 'right':return{opacity:0,translate:X+'px 0px'};case 'down':return{opacity:0,translate:'0px '+(-Y*dir)+'px'};default:return{opacity:0,translate:'0px '+(Y*dir)+'px'};}}
